/** Material Symbols: viewBox "0 -960 960 960" — сдвиг на 960 по вертикали. */
private fun rounded(name: String, path: String, autoMirror: Boolean = false): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
        autoMirror = autoMirror
    ).group(translationY = 960f) {
        addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black))
    }.build()

/** Залитые иконки старого формата Symbols: координаты 24 × 24 без viewBox. */
private fun legacy24(name: String, path: String, autoMirror: Boolean = false): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
        autoMirror = autoMirror
    ).apply {
        addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black))
    }.build()
